examples.code:
def flip(i, c):
    # even positions go lower, odd positions go upper
    if i % 2 == 0:
        return c.lower()
    return c.upper()

# enumerate hands out each character with its position
print(''.join(flip(i, c) for i, c in enumerate('Hello, world!')))

def cut(w):
    # the index of the first vowel
    for i, c in enumerate(w):
        if c in 'aeiouy':
            return i
    return len(w)

def pig(w):
    k = cut(w)
    ending = 'yay' if k == 0 else 'ay'
    return w[k:] + w[:k] + ending

print(' '.join(pig(w) for w in 'my name is al'.split()))
